// ─── SVG path parser → flat [x,y] polyline sequences ────────────────────────
function parseSvgPath(d: string): [number, number][][] {
  const chains: [number, number][][] = [];
  let current: [number, number][] = [];
  let cx = 0, cy = 0;

  // Tokenise: split on command letters, keeping the letter
  const tokens = d.match(/[MLHVCSQTAZmlhvcsqtaz][^MLHVCSQTAZmlhvcsqtaz]*/g) || [];

  for (const token of tokens) {
    const cmd = token[0];
    const args = token.slice(1).trim().split(/[\s,]+/).filter(Boolean).map(Number);

    if (cmd === 'M' || cmd === 'm') {
      if (current.length > 1) chains.push(current);
      current = [];
      for (let i = 0; i < args.length; i += 2) {
        if (cmd === 'M') { cx = args[i]; cy = args[i + 1]; }
        else { cx += args[i]; cy += args[i + 1]; }
        current.push([cx, cy]);
      }
    } else if (cmd === 'L' || cmd === 'l') {
      for (let i = 0; i < args.length; i += 2) {
        if (cmd === 'L') { cx = args[i]; cy = args[i + 1]; }
        else { cx += args[i]; cy += args[i + 1]; }
        current.push([cx, cy]);
      }
    } else if (cmd === 'H') {
      for (let i = 0; i < args.length; i++) { cx = args[i]; current.push([cx, cy]); }
    } else if (cmd === 'h') {
      for (let i = 0; i < args.length; i++) { cx += args[i]; current.push([cx, cy]); }
    } else if (cmd === 'V') {
      for (let i = 0; i < args.length; i++) { cy = args[i]; current.push([cx, cy]); }
    } else if (cmd === 'v') {
      for (let i = 0; i < args.length; i++) { cy += args[i]; current.push([cx, cy]); }
    } else if (cmd === 'Z' || cmd === 'z') {
      if (current.length > 1) { current.push([...current[0]]); chains.push(current); }
      current = [];
    } else if (cmd === 'C' || cmd === 'c') {
      // Cubic bezier — sample it
      for (let i = 0; i < args.length; i += 6) {
        const x1 = cmd === 'C' ? args[i]   : cx + args[i];
        const y1 = cmd === 'C' ? args[i+1] : cy + args[i+1];
        const x2 = cmd === 'C' ? args[i+2] : cx + args[i+2];
        const y2 = cmd === 'C' ? args[i+3] : cy + args[i+3];
        const ex = cmd === 'C' ? args[i+4] : cx + args[i+4];
        const ey = cmd === 'C' ? args[i+5] : cy + args[i+5];
        for (let t = 0.1; t <= 1.0; t += 0.1) {
          const mt = 1 - t;
          current.push([
            mt*mt*mt*cx + 3*mt*mt*t*x1 + 3*mt*t*t*x2 + t*t*t*ex,
            mt*mt*mt*cy + 3*mt*mt*t*y1 + 3*mt*t*t*y2 + t*t*t*ey,
          ]);
        }
        cx = ex; cy = ey;
      }
    }
  }
  if (current.length > 1) chains.push(current);
  return chains;
}

// Pre-parse all paths once at module load
const PARSED_CHAINS: [number, number][][][] = RAW_PATHS.map(d => parseSvgPath(d));

// ─── Component ───────────────────────────────────────────────────────────────
export default function Hero() {
  const sectionRef = useRef<HTMLElement>(null);
  const canvasRef  = useRef<HTMLCanvasElement>(null);
  const rafRef     = useRef<number>(0);

  // Smooth cursor state — all in SVG coordinate space (0..794, 0..445)
  const cursorSvg  = useRef({ x: 397, y: 222, active: false });
  const smoothCursor = useRef({ x: 397, y: 222 });

  // Idle breathing
  const idleT = useRef(0);

  // Ambient color cursor — follows phantom cursor (or real cursor) position
  const colorCursor = useRef({ x: 397, y: 222 });

  // Phantom cursor — drives lens warp autonomously when no real cursor is present.
  // Starts near top-left corner. Velocity uses irrational-ratio sine accelerations
  // so the path never visibly repeats within a session.
  const phantomCursor = useRef({ x: 60, y: 40, vx: 0.55, vy: 0.35 });

  // Click burst state — tracks a distortion shockwave
  // phase: 0 = idle, 1 = bursting (radius shrinking), 2 = healing (radius recovering)
  const burst = useRef({ active: false, progress: 0 });

  const reduced = useReducedMotion();

  // Ref so the RAF closure always reads the current reduced-motion value
  // (initialised false; sync effect below corrects it before meaningful use)
  const reducedRef  = useRef(false);

  const [inHero, setInHero] = useState(true);
  const [cursorScreen, setCursorScreen] = useState({ x: -999, y: -999 });
  const [cursorVisible, setCursorVisible] = useState(false);

  // Hide system cursor over hero
  useEffect(() => {
    document.body.style.cursor = inHero ? "none" : "auto";
    return () => { document.body.style.cursor = "auto"; };
  }, [inHero]);

  // Mouse tracking
  useEffect(() => {
    const onMove = (e: MouseEvent) => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const rect = canvas.getBoundingClientRect();
      // Map screen → SVG coordinate space
      const scaleX = 794 / rect.width;
      const scaleY = 445 / rect.height;
      cursorSvg.current = {
        x: (e.clientX - rect.left) * scaleX,
        y: (e.clientY - rect.top)  * scaleY,
        active: true,
      };
      setCursorScreen({ x: e.clientX, y: e.clientY });
      setCursorVisible(true);
    };
    const onLeave  = () => {
      setCursorVisible(false);
      cursorSvg.current.active = false;
      // Sync phantom to where the real cursor was so there's no visual jump
      phantomCursor.current.x = smoothCursor.current.x;
      phantomCursor.current.y = smoothCursor.current.y;
    };
    const onEnter  = () => setCursorVisible(true);
    const onClick = () => {
      // Trigger a fresh burst from wherever the cursor currently is
      burst.current = { active: true, progress: 0 };
    };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseleave", onLeave);
    window.addEventListener("mouseenter", onEnter);
    window.addEventListener("click", onClick);
    return () => {
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseleave", onLeave);
      window.removeEventListener("mouseenter", onEnter);
      window.removeEventListener("click", onClick);
    };
  }, []);

  // IntersectionObserver for hero visibility
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([entry]) => setInHero(entry.isIntersecting),
      { threshold: 0.1 }
    );
    if (sectionRef.current) obs.observe(sectionRef.current);
    return () => obs.disconnect();
  }, []);

  // Keep reducedRef in sync with the OS reduced-motion preference
  useEffect(() => { reducedRef.current = reduced; }, [reduced]);

  // Canvas resize handler
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const resize = () => {
      canvas.width  = canvas.offsetWidth  * window.devicePixelRatio;
      canvas.height = canvas.offsetHeight * window.devicePixelRatio;
    };
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(canvas);
    return () => ro.disconnect();
  }, []);

  // ── Main RAF loop ──────────────────────────────────────────────────────────
  useEffect(() => {
    const LERP          = 0.06;   // cursor smoothing
    const LENS_R        = 100;    // lens radius in SVG units (your tuned value)
    const LENS_STRENGTH = 4;      // max push distance in SVG units (your tuned value)
    const IDLE_SPEED    = 0.00018;
    const IDLE_AMP      = 5;      // max idle warp in SVG units
    const IDLE_R        = 200;    // idle pulse radius

    // Burst config
    const BURST_R_START   = 1;   // radius at peak shatter — in the aliasing sweet spot
    const BURST_DURATION  = 500;  // total ms for the full burst → heal cycle
    const BURST_SHATTER   = 0.10; // fraction of duration spent in shatter phase (0→1)

    let burstStartTime = 0;
    let fadeStartTime  = 0;

    const draw = (now: number) => {
      if (fadeStartTime === 0) fadeStartTime = now;
      rafRef.current = requestAnimationFrame(draw);
      idleT.current += IDLE_SPEED;

      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      const W = canvas.width;
      const H = canvas.height;
      const dpr = window.devicePixelRatio || 1;

      const scaleX = W / 794;
      const scaleY = H / 445;

      // Smooth cursor
      const target = cursorSvg.current;
      smoothCursor.current.x += (target.x - smoothCursor.current.x) * LERP;
      smoothCursor.current.y += (target.y - smoothCursor.current.y) * LERP;
      const mx = smoothCursor.current.x;
      const my = smoothCursor.current.y;

      // ── Phantom cursor (autonomous lens warp) ─────────────────────────────
      // When no real cursor is active, a phantom cursor wanders the SVG canvas
      // using velocity that is continuously nudged by overlapping sine waves at
      // irrational frequency ratios — so the trajectory never looks periodic.
      // Soft edge repulsion keeps it from dwelling in corners too long.
      // The real cursor takes over seamlessly when present.
      const isReduced = reducedRef.current;

      if (!cursorSvg.current.active && !isReduced) {
        const ph = phantomCursor.current;
        const t = now / 1000; // seconds

        // Acceleration nudges — three overlapping waves, irrational ratios
        const ax = Math.sin(t * 0.17) * 0.0028
                 + Math.sin(t * 0.41) * 0.0015
                 + Math.sin(t * 0.97) * 0.0007;
        const ay = Math.cos(t * 0.23) * 0.0028
                 + Math.cos(t * 0.53) * 0.0015
                 + Math.cos(t * 1.13) * 0.0007;
        ph.vx += ax;
        ph.vy += ay;

        // Speed cap — prevents runaway velocity
        const speed = Math.sqrt(ph.vx * ph.vx + ph.vy * ph.vy);
        const MAX_SPEED = 1.4;
        if (speed > MAX_SPEED) { ph.vx *= MAX_SPEED / speed; ph.vy *= MAX_SPEED / speed; }

        // Soft edge repulsion — smoothly pushes away from SVG bounds
        const MARGIN = 70;
        if (ph.x < MARGIN)       ph.vx += (MARGIN - ph.x)       * 0.0018;
        if (ph.x > 794 - MARGIN) ph.vx -= (ph.x - (794 - MARGIN)) * 0.0018;
        if (ph.y < MARGIN)       ph.vy += (MARGIN - ph.y)       * 0.0018;
        if (ph.y > 445 - MARGIN) ph.vy -= (ph.y - (445 - MARGIN)) * 0.0018;

        ph.x += ph.vx;
        ph.y += ph.vy;
      }

      // lensX/lensY: what the lens warp actually uses
      const lensX = cursorSvg.current.active ? mx : phantomCursor.current.x;
      const lensY = cursorSvg.current.active ? my : phantomCursor.current.y;

      // Color cursor lerps toward lens position (slower ambient, faster real)
      const colorLerp    = cursorSvg.current.active ? 0.08 : 0.018;
      colorCursor.current.x += (lensX - colorCursor.current.x) * colorLerp;
      colorCursor.current.y += (lensY - colorCursor.current.y) * colorLerp;
      const cmx = colorCursor.current.x;
      const cmy = colorCursor.current.y;
      // ──────────────────────────────────────────────────────────────────────

      // ── Burst radius calculation ──────────────────────────────────────────
      // When a click fires, burst.active becomes true and we track elapsed time.
      // The lens radius drops sharply from LENS_R → BURST_R_START (shatter phase),
      // then eases back up to LENS_R (heal phase) using a smooth cubic curve.
      let activeLensR = LENS_R;

      if (burst.current.active) {
        if (burstStartTime === 0) burstStartTime = now;
        const elapsed = now - burstStartTime;
        const progress = Math.min(elapsed / BURST_DURATION, 1);

        if (progress < BURST_SHATTER) {
          // Fast drop: LENS_R → BURST_R_START
          const t = progress / BURST_SHATTER;
          // Ease in (accelerate into shatter)
          const eased = t * t;
          activeLensR = LENS_R + (BURST_R_START - LENS_R) * eased;
        } else {
          // Slow heal: BURST_R_START → LENS_R
          const t = (progress - BURST_SHATTER) / (1 - BURST_SHATTER);
          // Ease out with overshoot-free cubic
          const eased = 1 - Math.pow(1 - t, 3);
          activeLensR = BURST_R_START + (LENS_R - BURST_R_START) * eased;
        }

        if (progress >= 1) {
          burst.current.active = false;
          burstStartTime = 0;
          activeLensR = LENS_R;
        }
      }
      // ─────────────────────────────────────────────────────────────────────

      ctx.clearRect(0, 0, W, H);
      ctx.lineJoin = "round";
      ctx.lineCap  = "butt";

      // Cursor-following gradient: Terracotta (close) → Cream (mid) → Slate Blue (far)
      const GRADIENT_STOPS = [
        { r: 209, g: 107, b:  71 }, // #D16B47 Terracotta — at cursor
        { r: 232, g: 220, b: 204 }, // #E8DCCC Cream      — mid distance
        { r: 115, g: 140, b: 199 }, // #738CC7 Slate Blue — far from cursor
      ];

      // Max distance (SVG units) at which the gradient reaches its far colour
      const COLOR_RADIUS = 380;

      const interpColor = (t: number) => {
        const scaled = t * (GRADIENT_STOPS.length - 1);
        const lo = Math.floor(scaled);
        const hi = Math.min(lo + 1, GRADIENT_STOPS.length - 1);
        const frac = scaled - lo;
        const a = GRADIENT_STOPS[lo];
        const b = GRADIENT_STOPS[hi];
        return {
          r:  Math.round(a.r + (b.r - a.r) * frac),
          g:  Math.round(a.g + (b.g - a.g) * frac),
          bl: Math.round(a.b + (b.b - a.b) * frac),
        };
      };

      PARSED_CHAINS.forEach((chains, pathIdx) => {
        const lw = 0.6 * Math.min(scaleX, scaleY) / dpr * dpr;
        ctx.lineWidth = lw;

        chains.forEach((pts) => {
          if (pts.length < 2) return;

          // First pass: compute warped canvas positions for all points
          const warped: [number, number][] = pts.map(([px, py]) => {
            const dx = px - lensX;
            const dy = py - lensY;
            const dist = Math.sqrt(dx * dx + dy * dy);
            let wx = px, wy = py;
            if (dist < activeLensR && dist > 0.001) {
              const norm = dist / activeLensR;
              const falloff = Math.pow(Math.sin(norm * Math.PI), 1.4);
              const push = falloff * LENS_STRENGTH;
              wx = px + (dx / dist) * push;
              wy = py + (dy / dist) * push;
            }
            const tIdle = idleT.current;
            const idxNorm = pathIdx / PARSED_CHAINS.length;
            const phase = idxNorm * Math.PI * 2;
            const breath = Math.sin(tIdle + phase) * IDLE_AMP;
            const cxSvg = 397, cySvg = 222;
            const fromCx = wx - cxSvg;
            const fromCy = wy - cySvg;
            const fromCDist = Math.sqrt(fromCx * fromCx + fromCy * fromCy);
            if (fromCDist > 0.001) {
              const idleFalloff = Math.max(0, 1 - fromCDist / IDLE_R);
              const idlePush = breath * idleFalloff * 0.6;
              wx += (fromCx / fromCDist) * idlePush;
              wy += (fromCy / fromCDist) * idlePush;
            }
            return [wx * scaleX, wy * scaleY];
          });

          // Second pass: draw each segment coloured by its midpoint distance from cursor.
          // Midpoint-to-midpoint quadratic beziers: each data point is a control point,
          // midpoints between consecutive points are the on-curve anchors. This smooths
          // the polyline into a continuous curve with no angular joints or dot artifacts.
          for (let i = 0; i < warped.length - 1; i++) {
            const [x0, y0] = warped[i];
            const [x1, y1] = warped[i + 1];
            // On-curve start: midpoint of prev→current (exact point at chain start)
            const sx = i === 0 ? x0 : (warped[i - 1][0] + x0) / 2;
            const sy = i === 0 ? y0 : (warped[i - 1][1] + y0) / 2;
            // On-curve end: midpoint of current→next (exact point at chain end)
            const ex = i === warped.length - 2 ? x1 : (x0 + x1) / 2;
            const ey = i === warped.length - 2 ? y1 : (y0 + y1) / 2;
            // Midpoint back in SVG units for distance measurement
            const midSvgX = (x0 + x1) / 2 / scaleX;
            const midSvgY = (y0 + y1) / 2 / scaleY;
            const midDist = Math.sqrt((midSvgX - cmx) ** 2 + (midSvgY - cmy) ** 2);
            // Smoothstep 0 (at cursor) → 1 (at COLOR_RADIUS)
            const tRaw = Math.min(midDist / COLOR_RADIUS, 1);
            const tEased = tRaw * tRaw * (3 - 2 * tRaw);
            const { r, g, bl } = interpColor(tEased);
            const fadeRaw = Math.min((now - fadeStartTime) / 2000, 1);
            const fadeIn  = fadeRaw * fadeRaw * (3 - 2 * fadeRaw); // smoothstep
            const alpha = (0.78 - tEased * 0.28) * fadeIn;
            ctx.strokeStyle = `rgba(${r}, ${g}, ${bl}, ${alpha})`;
            ctx.beginPath();
            ctx.moveTo(sx, sy);
            ctx.quadraticCurveTo(x0, y0, ex, ey);
            ctx.stroke();
          }
        });
      });
    };

    rafRef.current = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(rafRef.current);
  }, []);

  return (
    <section
      ref={sectionRef}
      className="relative w-full h-screen overflow-hidden cursor-none"
    >
      {/* Canvas layer */}
      <canvas
        ref={canvasRef}
        className="absolute inset-0 w-full h-full pointer-events-none"
        aria-hidden="true"
      />

      {/* Coordinates — quiet top-left label */}
      <motion.p
        className="absolute top-16 left-7 text-[11px] tracking-[0.25em] text-black/30 pointer-events-none"
        initial={reduced ? undefined : { opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={reduced ? undefined : { duration: 1.2, delay: 1.4, ease: [0.25, 0.1, 0.25, 1] }}
      >
        45.9237° N &nbsp; 6.8694° E &nbsp;—&nbsp; Chamonix, France
      </motion.p>

      {/* me. mark — centered */}
      <motion.div
        className="absolute pointer-events-none"
        style={{ top: "50%", left: "50%", transform: "translate(-50%, -50%)" }}
        initial={reduced ? undefined : { opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={reduced ? undefined : { duration: 1.6, delay: 0.4, ease: [0.25, 0.1, 0.25, 1] }}
      >
        <img
          src={meLogo}
          alt="me."
          style={{ width: "clamp(180px, 28vw, 340px)", height: "auto", display: "block" }}
          draggable={false}
        />
      </motion.div>

      {/* Scroll indicator — bottom-right */}
      <motion.p
        className="absolute bottom-8 right-7 text-[10px] font-medium uppercase tracking-[0.14em] text-black/30"
        initial={reduced ? undefined : { opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={reduced ? undefined : { duration: 1.2, delay: 1.8, ease: [0.25, 0.1, 0.25, 1] }}
      >
        scroll ↓
      </motion.p>

      {/* GPS cursor */}
      <div
        className="fixed pointer-events-none z-50"
        style={{
          left: cursorScreen.x,
          top: cursorScreen.y,
          transform: "translate(-50%, -50%)",
          opacity: cursorScreen.x === -999 || !inHero || !cursorVisible ? 0 : 1,
          transition: "opacity 0.3s ease",
        }}
      >
        <div className="absolute rounded-full" style={{ width: 48, height: 48, top: "50%", left: "50%", transform: "translate(-50%, -50%)", background: "conic-gradient(from 200deg, transparent 0deg, rgba(100, 80, 50, 0.12) 60deg, transparent 120deg)", animation: "fan-pulse 3.5s ease-out infinite" }} />
        <div className="absolute rounded-full" style={{ width: 48, height: 48, top: "50%", left: "50%", transform: "translate(-50%, -50%)", background: "conic-gradient(from 200deg, transparent 0deg, rgba(100, 80, 50, 0.07) 60deg, transparent 120deg)", animation: "fan-pulse 3.5s ease-out infinite 1.2s" }} />
        <div className="absolute rounded-full" style={{ width: 20, height: 20, top: "50%", left: "50%", transform: "translate(-50%, -50%)", background: "rgba(100, 80, 50, 0.06)", border: "1px solid rgba(100, 80, 50, 0.18)" }} />
        <div className="absolute rounded-full" style={{ width: 9, height: 9, top: "50%", left: "50%", transform: "translate(-50%, -50%)", background: "radial-gradient(circle at 35% 35%, #6B9FD4, #2E6DB4)", boxShadow: "0 0 0 1.5px rgba(255,255,255,0.8), 0 1px 4px rgba(46,109,180,0.4)" }} />
      </div>

      <style>{`
        @keyframes fan-pulse {
          0%   { transform: translate(-50%, -50%) scale(0.6); opacity: 0.9; }
          60%  { opacity: 0.4; }
          100% { transform: translate(-50%, -50%) scale(2.8); opacity: 0; }
        }
      `}</style>
    </section>
  );
}
